#overlay #depMain.pg.hub.camp-detail .dep-foot { display: flex; align-items: center; gap: 24px; flex: none; margin: 0; padding: 24px 38px; background: #e2e7db; border-top: 1px solid #b6c4b0; }
#overlay #depMain.pg.hub.camp-detail .dep-capacity { color: #4d7269; font-size: 17px; }
#overlay #depMain.pg.hub.camp-detail .dep-capacity b { color: #2e5d66; }
#overlay #depMain.pg.hub.camp-detail .camp-depart-next { margin-left: auto; color: #71836c; font-size: 14px; }
#overlay #depMain.pg.hub.camp-detail #btnDeploy { width: 300px; min-height: 58px; flex: none; padding: 14px 25px; font-size: 21px; }
#overlay #depMain.pg.hub.camp-detail :is(.dep-status, .ov-empty, .dep-no-results) { color: #6d816b; font-size: 16px; line-height: 1.8; }
#overlay #depMain.pg.hub.camp-detail .dep-status { margin: 0; padding: 12px 40px; background: #e9dcc3; color: #795b35; }
 #overlay .card:has(.preparation-shell.camp-detail) { background: #efeee4; border: 1px solid #b6c4b4; color: #36574f; }
#cardZoom:has(.camp-detail), body:has(#depMain.camp-detail) #cardZoom { background: transparent; }
#cardZoom:has(.camp-detail) .cz-foot, body:has(#depMain.camp-detail) #cardZoom .cz-foot { position: relative; max-width: 950px; width: calc(100% - 80px); margin: 20px auto; background: #f1efe1; color: #365b50; padding: 22px 30px; border: 1px solid #c8d4bd; border-radius: 2px; text-align: left; }
#cardZoom:has(.camp-detail) :is(.ov-note, .gold), body:has(#depMain.camp-detail) #cardZoom .dep-n { color: #496c5a; font-size: 16px; text-shadow: none; }
#cardZoom:has(.camp-detail) .ov-btn { background: #e4e9d7; color: #3b6653; border: 1px solid #aabc9f; border-radius: 2px; min-height: 42px; padding: 10px 16px; font-size: 16px; box-shadow: none; }
#cardZoom:has(.camp-detail) .ov-btn.ok { background: #356d70; color: #fff8df; }
#cardZoom:has(.camp-detail) .cz-note { display: none; }
#cardZoom:has(.camp-card-actions) .cz-foot { background: transparent; border: 0; box-shadow: none; padding: 0; }
#cardZoom:has(.camp-card-actions) { background: transparent; }
#cardZoom:has(.camp-card-actions) .cz-foot { width: min(440px, calc(100% - 48px)); max-width: none; margin: 14px auto 0; color: #d5e1e6; }
#cardZoom .camp-card-actions { display: flex; flex-direction: column; align-items: center; gap: 14px; }
#cardZoom .camp-card-actions .inspect-meta { display: flex; align-items: center; justify-content: space-between; gap: 24px; width: min(340px, 100%); padding: 0 0 12px; border-bottom: 1px solid #a8bfcd26; }
#cardZoom .camp-card-actions :is(.inspect-count) { color: #a2b5bf; font-size: 12px; }
#cardZoom .camp-card-actions .ov-btns { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; width: auto; margin: 0; }
#cardZoom .camp-card-actions .ov-btn { flex: 0 0 auto; width: auto; min-width: 100px; min-height: 36px; padding: 8px 14px; border: 1px solid #748b985c; border-radius: 3px; clip-path: none; background: #25343f; color: #d7e2e9; font: 600 14px/1.4 var(--font-ui); letter-spacing: .04em; box-shadow: none; }
#cardZoom .camp-card-actions .ov-btn.ok { background: #31545e; border-color: #5c8f9d99; color: #edf7fa; }
#cardZoom .camp-card-actions .ov-btn:hover { background: #3a4e5c; transform: none; }
#cardZoom .camp-card-actions .ov-btn.ok:hover { background: #406e79; }
#cardZoom:has(.camp-card-actions) .cz-close { width: 36px; height: 36px; background: #17232ed9; border: 1px solid #96adbb52; color: #cbdbe5; }
body:has(#hubMain.base-camp, .cls-pool-page[data-base-departure="true"]) #cardZoom { background: transparent; }
body:has(#hubMain.base-camp, .cls-pool-page[data-base-departure="true"]) #cardZoom .cz-note { background: #f1efe1; border: 1px solid #c1cfba; color: #496f61; padding: 18px 24px; border-radius: 2px; }
body:has(#hubMain.base-camp, .cls-pool-page[data-base-departure="true"]) #cardZoom :is(.cz-note-tag, .cz-note-text) { color: #496f61; font: 15px/1.6 var(--font-ui); }

/* 基地的外壳/内容归属由页面动效配置决定，通用导演不覆盖页内动画。 */
@keyframes camp-page-in { from { opacity: .4; transform: translateY(9px); } to { opacity: 1; transform: none; } }
body.reduce-motion #overlay #hubMain.pg.hub.base-camp *, body.reduce-motion #overlay #depMain.pg.hub.camp-detail * { animation: none !important; transition: none !important; }
@media (prefers-reduced-motion: reduce) {
  #overlay #hubMain.pg.hub.base-camp *, #overlay #depMain.pg.hub.camp-detail * { animation: none; transition: none; }
  #overlay #hubMain.pg.hub.base-camp .hub-page.page-in { animation: none; }
}

changes.before:
/* v7 基地房间：开放陈列、大立绘、单一阅读纸；只改变房间画布，不改卡牌身份与特写。 */
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage .hub-page:has(> :is(.warehouse-v3,.personnel-v2,.trade-v5,.hub-archive-v3,.facilities-v2)) {
  --camp-bg:#242a29; --camp-paper:#242a29; --camp-sheet:#e6e1d6;
  --camp-ink:#eeeae1; --camp-muted:#a9b0a9; --camp-sub:#a9b0a9;
  --camp-line:#d3d8ce24; --camp-dark:#303937; --camp-accent:#bac2b3;
  --camp-brass:#b9c1b3; --camp-blue:#b9c1b3; --camp-action:#a76344;
  --camp-action-hover:#bc7752; --camp-room-hover:#eeeae109; --camp-room-selected:#dfe7d111;
  --room-gap:clamp(28px,calc(var(--game-layout-width, 100vw) * 0.038),64px); --room-pad:clamp(28px,calc(var(--game-layout-width, 100vw) * 0.044000000000000004),76px);
  color:var(--camp-ink); background:linear-gradient(115deg,#2b3330,#242a29 66%);
  padding:32px var(--room-pad) 40px; scrollbar-color:#a9b0a950 transparent;
}
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage :is(.warehouse-v3,.personnel-v2,.trade-v5,.hub-archive-v3,.facilities-v2) {
  width:100%; max-width:none; min-width:0; margin:0; box-sizing:border-box;
}
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage :is(.warehouse-v3,.personnel-v2,.hub-archive-v3,.facilities-v2) > :is(.camp-section-head,.av3-header),
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage .trade-v5-heading {
  display:flex; flex-direction:row; align-items:baseline; flex-wrap:wrap; gap:20px 36px;
  padding:0 0 24px; margin:0 0 30px; border:0; border-bottom:1px solid var(--camp-line);
}
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage :is(.warehouse-v3,.personnel-v2,.hub-archive-v3,.facilities-v2,.trade-v5) > :is(.camp-section-head,.av3-header,.trade-v5-heading) h2 {
  padding:0; margin:0; border:0; color:var(--camp-ink); font:500 clamp(34px,calc(var(--game-layout-width, 100vw) * 0.03),46px)/1.2 var(--font-ui);
  letter-spacing:.06em; text-shadow:none; white-space:normal;
}
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage :is(.person-utilities,.warehouse-header-actions) {
  display:flex; flex-wrap:wrap; align-items:center; gap:24px; margin-left:auto;
}
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage :is(.warehouse-v3,.personnel-v2,.trade-v5,.hub-archive-v3,.facilities-v2) :is(.base-link,.person-utilities button) {
  padding:8px 0; border:0; background:transparent; color:var(--camp-muted);
  font:500 18px/1.45 var(--font-ui); letter-spacing:.02em; transition:color 160ms ease;
}

/* 浏览工具与内容共用一条基线，分类用字与下划线表达。 */
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage :is(.archive-toolbar) {
  display:flex; flex-wrap:wrap; align-items:center; gap:16px 28px; margin:0 0 30px; padding:0 0 18px;
  border:0; border-bottom:1px solid var(--camp-line); background:transparent;
}
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage :is(.archive-toolbar) :is(input,select) {
  box-sizing:border-box; width:auto; max-width:100%; min-height:44px; padding:8px 2px;
  border:0; border-bottom:1px solid var(--camp-line); border-radius:0; background:transparent;
  color:var(--camp-ink); font:18px/1.4 var(--font-ui); box-shadow:none;
}
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage :is(.archive-toolbar) select option { background:#242a29; color:#eeeae1; }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage :is(.archive-status,.trade-v5-modes) { display:flex; flex-wrap:wrap; gap:24px; background:none; }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage :is(.archive-status,.trade-v5-modes) :is(button,.mini-btn) {
  width:auto; min-width:0; min-height:42px; padding:8px 0; border:0; border-bottom:1px solid transparent;
  border-radius:0; color:var(--camp-muted); background:none; box-shadow:none; font:500 19px/1.4 var(--font-ui);
}
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage :is(.archive-status,.trade-v5-modes) :is(.on,.ok,.is-selected) {
  color:var(--camp-ink); background:none; border-bottom-color:var(--camp-accent); box-shadow:none;
}

/* 仓库：整页卡牌货架，筛选展开为宽工具区，画作保持原色。 */
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage .warehouse-v3 .camp-section-head .base-resource-strip { margin:0 0 0 auto; gap:18px; font-size:16px; }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage .warehouse-header-actions { gap:20px; }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage .warehouse-capacity { display:flex; align-items:baseline; gap:18px; }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage .warehouse-v3 .camp-page-stat { margin:0; color:var(--camp-muted); font:18px/1.4 var(--font-num); }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage .warehouse-purpose {
  display:flex; align-items:center; flex-wrap:wrap; gap:18px; justify-content:space-between;
  margin:0 0 24px; padding:14px 0; border:0; border-bottom:1px solid var(--camp-line); background:none;
}
/* 主线提供独立分类节点时，采用 1999 仓库的左分类 + 宽货架骨架。 */
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage .warehouse-v3:has(> .warehouse-categories-v7) {
  display:grid; grid-template-columns:minmax(155px,16%) minmax(0,1fr); grid-template-rows:auto auto auto minmax(400px,1fr); gap:0 34px;
}
