#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage .hub-archive-v3 .story-list { flex-direction:row; gap:28px; padding:0; border:0; border-bottom:1px solid var(--camp-line); }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage .hub-archive-v3 .story-entry { flex:1; grid-template-columns:40px minmax(0,1fr); padding:14px 0 20px; border:0; border-bottom:1px solid transparent; background:none; }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage .hub-archive-v3 .story-entry.on { background:none; border-bottom-color:var(--camp-accent); }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage .hub-archive-v3 .story-reader { min-height:500px; padding:40px clamp(36px,calc(var(--game-layout-width, 100vw) * 0.06),100px); border:1px solid #edf1ef24; background:#151c22; }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage .hub-archive-v3 .story-reader p { font-size:22px; line-height:1.9; max-width:860px; }

/* 扩建：设施分成开放的大陈列，关键容量留在阅读区。 */
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage .facility-layout { grid-template-columns:minmax(0,1.4fr) minmax(340px,.85fr); gap:var(--room-gap); padding-top:0; }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage .facility-map { gap:28px; }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage .facility-tile { align-items:flex-start; padding:28px; gap:22px; border:0; border-bottom:1px solid var(--camp-line); background:none; box-shadow:none; }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage .facility-tile.on { background:var(--camp-room-selected); border-bottom-color:var(--camp-accent); }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage .facility-art { width:200px; max-width:100%; height:200px; align-self:center; color:#bdc4b8; }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage .facility-tile h3 { font-size:28px; }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage .facility-tile b { font-size:35px; }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage .facility-details { align-self:start; }

/* 只控制房间内的操作按钮，仓库特写的 footer 与 camp-card-actions 不进入此作用域。 */
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage :is(.personnel-v2,.trade-v5,.hub-archive-v3,.facilities-v2) button.base-command[data-act] {
  min-height:52px; padding:13px 20px; border:1px solid var(--camp-line); border-radius:0;
  color:var(--camp-ink); background:none; box-shadow:none; clip-path:none; transform:none;
  font:500 19px/1.45 var(--font-ui); transition:background 160ms ease,color 160ms ease,border-color 160ms ease;
}
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage :is(.personnel-v2,.trade-v5,.hub-archive-v3,.facilities-v2) button.base-command[data-act].base-command-primary { color:#fff5e9; background:var(--camp-action); border-color:transparent; }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage .trade-v5-checkout button.base-command[data-act].is-confirming { color:#fff5e9; background:#8c5038; border-color:transparent; }
#overlay#overlay #hubMain.pg.hub.base-camp.base-frame-v7.base-subpage :is(.warehouse-v3,.personnel-v2,.trade-v5,.hub-archive-v3,.facilities-v2) [hidden] { display:none; }
@media (prefers-reduced-motion:reduce) {
}
